##ALBERTO_PS##
# ZAR one-click updater. Generated by tools/make_update.py - do not edit the .cmd by hand.
$ErrorActionPreference = 'Stop'
$UPD_VERSION = __VERSION__
$UPD_NOTES   = @'
__NOTES__
'@
$UPD_KEEP    = @(__KEEP__)
$UPD_MODE    = '__MODE__'          # full = whole ZAR, addons = only add new tools

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.IO.Compression.FileSystem
$Host.UI.RawUI.WindowTitle = "ZAR Update v$UPD_VERSION"
function Say($t, $c = 'Cyan') { Write-Host $t -ForegroundColor $c }
function Box($t, $icon = 'Information', $btn = 'OK') {
    [System.Windows.Forms.MessageBox]::Show($t, 'ZAR Update', $btn, $icon)
}
function Test-ZAR($p) {
    $p -and (Test-Path -LiteralPath (Join-Path $p 'main.py')) -and (Test-Path -LiteralPath (Join-Path $p 'actions'))
}

Say "=============================================="
Say "   ZAR UPDATE  -  version $UPD_VERSION"
Say "=============================================="

$self = $env:ALBERTO_UPD

# ---------- 1. Find ZAR ----------
$cfgDir  = Join-Path $env:LOCALAPPDATA 'ZARUpdater'
$cfgFile = Join-Path $cfgDir 'path.txt'
$cands = New-Object System.Collections.ArrayList
if (Test-Path -LiteralPath $cfgFile) { [void]$cands.Add((Get-Content -LiteralPath $cfgFile -Raw).Trim()) }
[void]$cands.Add((Split-Path $self -Parent))
foreach ($p in @("$env:LOCALAPPDATA\ZAR\app", 'C:\ZAR\Mark-XXXIX', 'C:\Windows\System32\Mark-XXXIX', 'C:\Mark-XXXIX',
                 "$env:USERPROFILE\Mark-XXXIX", "$env:USERPROFILE\Desktop\Mark-XXXIX",
                 "$env:USERPROFILE\Documents\Mark-XXXIX", "$env:USERPROFILE\Downloads\Mark-XXXIX",
                 "$env:USERPROFILE\OneDrive\Desktop\Mark-XXXIX")) { [void]$cands.Add($p) }
$target = $null
foreach ($c in $cands) { if (Test-ZAR $c) { $target = (Resolve-Path -LiteralPath $c).Path; break } }
if (-not $target) {
    Say "Searching for ZAR on this PC..." Yellow
    $found = @()
    foreach ($root in @('C:\ZAR', $env:USERPROFILE, 'C:\')) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        $depth = if ($root -eq 'C:\') { 2 } else { 4 }
        $found += Get-ChildItem -LiteralPath $root -Filter 'hud_bridge.py' -Recurse -Depth $depth -File -ErrorAction SilentlyContinue |
                  ForEach-Object { Split-Path (Split-Path $_.FullName -Parent) -Parent } |
                  Where-Object { Test-ZAR $_ }
        if ($found) { break }
    }
    $withVenv = $found | Where-Object { Test-Path -LiteralPath (Join-Path $_ 'venv') }
    if ($withVenv) { $target = @($withVenv)[0] } elseif ($found) { $target = @($found)[0] }
}
if (-not $target) {
    Box "I couldn't find ZAR automatically.`n`nIn the next window, select your ZAR folder (the one that contains main.py)." | Out-Null
    $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
    $dlg.Description = 'Select your ZAR folder (contains main.py)'
    if ($dlg.ShowDialog() -ne 'OK' -or -not (Test-ZAR $dlg.SelectedPath)) {
        Box "That folder is not ZAR (no main.py inside). Nothing was changed." 'Error' | Out-Null
        exit 1
    }
    $target = $dlg.SelectedPath
}
Say "ZAR found: $target" Green

# ---------- 2. Admin rights only if needed ----------
$probe = Join-Path $target ('.upd_probe_' + [guid]::NewGuid().ToString('N'))
try { [IO.File]::WriteAllText($probe, 'x'); Remove-Item -LiteralPath $probe -Force }
catch {
    $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    if ($isAdmin) { Box "Can't write to $target even as administrator. Nothing was changed." 'Error' | Out-Null; exit 1 }
    Say "ZAR's folder needs administrator rights - click YES on the next window." Yellow
    Start-Process -FilePath $env:ComSpec -ArgumentList "/c `"`"$self`"`"" -Verb RunAs
    exit 0
}

# ---------- 3. Version check ----------
$verFile = Join-Path $target $(if ($UPD_MODE -eq 'addons') { 'addons_version.txt' } else { 'version.txt' })
$current = 0
if (Test-Path -LiteralPath $verFile) { [int]::TryParse((Get-Content -LiteralPath $verFile -Raw).Trim(), [ref]$current) | Out-Null }
if ($current -ge $UPD_VERSION) {
    $r = Box "ZAR is already on version $current (this update is version $UPD_VERSION).`n`nInstall it anyway?" 'Question' 'YesNo'
    if ($r -ne 'Yes') { exit 0 }
}

# ---------- 4. Unpack ----------
Say "Unpacking update..."
$raw = [IO.File]::ReadAllText($self)
$dm  = '#' + '#ALBERTO_DATA#' + '#'
$b64 = $raw.Substring($raw.IndexOf($dm) + $dm.Length) -replace '[^A-Za-z0-9+/=]', ''
$tmp = Join-Path $env:TEMP ('alberto_upd_' + [guid]::NewGuid().ToString('N'))
$stage = Join-Path $tmp 'files'
New-Item -ItemType Directory -Force -Path $stage | Out-Null
$zipPath = Join-Path $tmp 'payload.zip'
[IO.File]::WriteAllBytes($zipPath, [Convert]::FromBase64String($b64))
[IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $stage)

# ---------- 5. Close ZAR ----------
Say "Closing ZAR..."
$guardianWasRunning = $false
$tl = $target.ToLower()
Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
    Where-Object { ($_.Name -like 'python*') -and ( ($_.ExecutablePath -and $_.ExecutablePath.ToLower().StartsWith($tl)) -or
                                                    ($_.CommandLine -and $_.CommandLine.ToLower().Contains($tl)) ) } |
    ForEach-Object {
        if ($_.CommandLine -and $_.CommandLine -like '*zar_guardian*') { $guardianWasRunning = $true }
        try { Stop-Process -Id $_.ProcessId -Force -ErrorAction Stop } catch {}
    }
Start-Sleep -Seconds 2

# ---------- 6. Copy files (with backup + rollback) ----------
$reqOld = Join-Path $target 'requirements.txt'
$reqOldHash = if (Test-Path -LiteralPath $reqOld) { (Get-FileHash -LiteralPath $reqOld).Hash } else { '' }
$stamp  = Get-Date -Format 'yyyyMMdd_HHmmss'
$backup = Join-Path $target "backups\before_v${UPD_VERSION}_$stamp"
$added = New-Object System.Collections.ArrayList
$changed = 0; $kept = 0
try {
    foreach ($f in Get-ChildItem -LiteralPath $stage -Recurse -File) {
        $rel  = $f.FullName.Substring($stage.Length + 1)
        $relN = $rel -replace '\\', '/'
        $dst  = Join-Path $target $rel
        $exists = Test-Path -LiteralPath $dst
        if ($exists -and ($UPD_KEEP -contains $relN)) { $kept++; continue }
        if ($exists) {
            if ((Get-FileHash -LiteralPath $dst).Hash -eq (Get-FileHash -LiteralPath $f.FullName).Hash) { continue }
            $b = Join-Path $backup $rel
            New-Item -ItemType Directory -Force -Path (Split-Path $b -Parent) | Out-Null
            Copy-Item -LiteralPath $dst -Destination $b -Force
        } else { [void]$added.Add($dst) }
        New-Item -ItemType Directory -Force -Path (Split-Path $dst -Parent) | Out-Null
        Copy-Item -LiteralPath $f.FullName -Destination $dst -Force
        $changed++
    }
} catch {
    Say "Error: $($_.Exception.Message) - restoring previous version..." Red
    if (Test-Path -LiteralPath $backup) {
        foreach ($b in Get-ChildItem -LiteralPath $backup -Recurse -File) {
            Copy-Item -LiteralPath $b.FullName -Destination (Join-Path $target $b.FullName.Substring($backup.Length + 1)) -Force
        }
    }
    foreach ($a in $added) { Remove-Item -LiteralPath $a -Force -ErrorAction SilentlyContinue }
    Box "The update failed and ZAR was restored to how it was.`n`n$($_.Exception.Message)" 'Error' | Out-Null
    exit 1
}
Say "Files updated: $changed" Green

# ---------- 7. New packages (only if requirements changed) ----------
$py = Join-Path $target 'venv\Scripts\python.exe'
if (-not (Test-Path -LiteralPath $py)) { $py = Join-Path (Split-Path $target -Parent) 'python\python.exe' }
if (-not (Test-Path -LiteralPath $py)) {
    $cmd = Get-Command python -ErrorAction SilentlyContinue
    if (-not $cmd) { $cmd = Get-Command py -ErrorAction SilentlyContinue }
    $py = if ($cmd) { $cmd.Source } else { '' }
}
$reqNewHash = if (Test-Path -LiteralPath $reqOld) { (Get-FileHash -LiteralPath $reqOld).Hash } else { '' }
$pipWarn = ''
if ($reqNewHash -and $reqNewHash -ne $reqOldHash) {
    if ($py -and (Test-Path -LiteralPath $py)) {
        Say "Installing new packages (this can take a few minutes)..."
        & $py -m pip install -r $reqOld --disable-pip-version-check -q
        if ($LASTEXITCODE -ne 0) {
            Say "Retrying packages one by one..." Yellow
            $failed = @()
            foreach ($line in Get-Content -LiteralPath $reqOld) {
                $pkg = $line.Trim()
                if (-not $pkg -or $pkg.StartsWith('#')) { continue }
                & $py -m pip install $pkg --disable-pip-version-check -q
                if ($LASTEXITCODE -ne 0) { $failed += $pkg }
            }
            if ($failed) { $pipWarn = "`n`nThese packages could not be installed: $($failed -join ', ')" }
        }
    } else { $pipWarn = "`n`nPython not found - run setup.bat once." }
}

# ---------- 7a. Add-ons: plug the new tools into this ZAR's own main.py ----------
$addonMsg = ''
if ($UPD_MODE -eq 'addons') {
    if ($py -and (Test-Path -LiteralPath $py)) {
        Say "Installing the new tools' packages..."
        & $py -m pip install pdf2docx pymupdf --disable-pip-version-check -q
        Say "Plugging the new tools into ZAR..."
        $out = & $py (Join-Path $target 'tools\addon_patch.py') 2>&1 | Out-String
        Say $out.Trim()
        if ($LASTEXITCODE -ne 0) { $addonMsg = "`n`nThe new tools were copied but could not be connected automatically:`n$($out.Trim())" }
    } else { $addonMsg = "`n`nPython not found - the new tools could not be connected." }
}

# ---------- 7b. LibreOffice (documents / PDF tools) ----------
$lo = @("$env:ProgramFiles\LibreOffice\program\soffice.exe", "${env:ProgramFiles(x86)}\LibreOffice\program\soffice.exe") |
      Where-Object { $_ -and (Test-Path -LiteralPath $_) }
if (-not $lo -and (Get-Command winget -ErrorAction SilentlyContinue)) {
    Say "Installing LibreOffice (a few minutes, please wait)..."
    & winget install -e --id TheDocumentFoundation.LibreOffice --silent --accept-package-agreements --accept-source-agreements | Out-Null
    if ($LASTEXITCODE -ne 0) { $pipWarn += "`n`nLibreOffice could not be installed automatically - ZAR will retry when you ask for it." }
}

# ---------- 8. Owner name (asked once per PC) ----------
$ownerFile = Join-Path $target 'config\owner.json'
if ($UPD_MODE -ne 'addons' -and -not (Test-Path -LiteralPath $ownerFile)) {
    Add-Type -AssemblyName Microsoft.VisualBasic
    $name = [Microsoft.VisualBasic.Interaction]::InputBox("What's your name?`n`nZAR will use it to talk to you (asked only once).", 'ZAR Update', '')
    if ($name -and $name.Trim()) {
        New-Item -ItemType Directory -Force -Path (Split-Path $ownerFile -Parent) | Out-Null
        [IO.File]::WriteAllText($ownerFile, (@{ name = $name.Trim() } | ConvertTo-Json))
    }
}

# ---------- 9. Clean up, remember path, restart ----------
New-Item -ItemType Directory -Force -Path $cfgDir | Out-Null
Set-Content -LiteralPath $cfgFile -Value $target
Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue
$bkRoot = Join-Path $target 'backups'
if (Test-Path -LiteralPath $bkRoot) {
    Get-ChildItem -LiteralPath $bkRoot -Directory | Sort-Object Name -Descending | Select-Object -Skip 5 |
        ForEach-Object { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue }
}

Say "Starting ZAR..." Green
# Start exactly ONE ZAR: the "ZAR" task (guardian, hidden) if it exists, otherwise the guardian, otherwise main.py
$guardian = Join-Path $target 'zar_guardian.pyw'
$pyw = if ($py) { Join-Path (Split-Path $py -Parent) 'pythonw.exe' } else { '' }
& schtasks /query /tn ZAR *> $null
if ($LASTEXITCODE -eq 0) {
    & schtasks /run /tn ZAR | Out-Null
} elseif ($pyw -and (Test-Path -LiteralPath $pyw) -and (Test-Path -LiteralPath $guardian)) {
    Start-Process -FilePath $pyw -ArgumentList 'zar_guardian.pyw' -WorkingDirectory $target
} elseif ($py -and (Test-Path -LiteralPath $py)) {
    Start-Process -FilePath $py -ArgumentList 'main.py' -WorkingDirectory $target
}

$notes = if ($UPD_NOTES.Trim()) { "`n`nWhat's new:`n$($UPD_NOTES.Trim())" } else { '' }
if ($UPD_MODE -eq 'addons') {
    Box "New tools added to ZAR (add-ons v$UPD_VERSION).`nEverything you had is kept as it was.$notes$addonMsg$pipWarn" | Out-Null
} else {
    Box "ZAR updated to version $UPD_VERSION.`nFiles changed: $changed$notes$pipWarn" | Out-Null
}
exit 0
